const partes = $input.item.json.content?.parts ?? [];
const texto = partes.map(p => p.text ?? '').join('\n');

// Como o JSON não tem chaves aninhadas, pega o último bloco {...} do texto
const blocos = texto.match(/\{[^{}]*\}/g);

let classificacao;
try {
  classificacao = JSON.parse(blocos[blocos.length - 1]);
} catch (e) {
  // Se não conseguir ler, escala para humano
  classificacao = {
    categoria: 'outros',
    urgencia: 'media',
    sentimento: 'neutro',
    confianca: 'baixa',
    resumo: 'Falha ao interpretar a resposta do modelo.'
  };
}

return {
  json: {
    reclamacao: $('Triagem de reclamações').item.json.body.reclamacao,
    ...classificacao
  }
};

const item = $input.item.json;

const categoriasValidas = [
  'item_faltando', 'pedido_errado', 'atraso', 'qualidade_comida',
  'problema_entregador', 'cobranca_indevida', 'risco_saude_seguranca', 'outros'
];

// Se o modelo inventar uma categoria fora da lista, trata como "outros"
let categoria = categoriasValidas.includes(item.categoria) ? item.categoria : 'outros';
let urgencia = item.urgencia;

// Regras de urgência mínima (mesmo que o modelo erre)
if (categoria === 'risco_saude_seguranca') urgencia = 'alta';
if (['cobranca_indevida', 'problema_entregador'].includes(categoria) && urgencia === 'baixa') {
  urgencia = 'media';
}

const acoes = {
  item_faltando: 'Reembolso parcial',
  pedido_errado: 'Reembolso total ou reenvio',
  atraso: 'Pedido de desculpas + cupom',
  qualidade_comida: 'Pedido de desculpas + reembolso parcial',
  problema_entregador: 'Escalar para humano',
  cobranca_indevida: 'Escalar para humano',
  risco_saude_seguranca: 'Escalar para humano (prioridade máxima)',
  outros: 'Escalar para humano'
};

// Casos que sempre vão para um humano
const escalar =
  ['problema_entregador', 'cobranca_indevida', 'risco_saude_seguranca', 'outros'].includes(categoria) ||
  item.confianca === 'baixa';

return {
  json: {
    ...item,
    categoria,
    urgencia,
    acao: escalar && !acoes[categoria].startsWith('Escalar')
      ? 'Escalar para humano (confiança baixa)'
      : acoes[categoria],
    escalar_humano: escalar
  }
};
